import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/ours-g2-3/bot.mjs';
import assert from 'node:assert/strict';

const base = { id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
// Helper: local Tokyo time -> Date (Tokyo is UTC+9, no DST)
const tokyo = (iso) => new Date(`${iso}+09:00`);

// 1. Daytime, first push allowed
let g = createPushGate();
assert.deepEqual(g.attempt(base, tokyo('2026-10-22T12:00:00')), { allowed: true, reason: null });

// 2. Quiet hours wrap past midnight: 23:30, 00:00 (start incl. of next day), 06:59 blocked; 07:00 allowed
g = createPushGate();
assert.equal(g.attempt(base, tokyo('2026-10-22T23:30:00')).reason, 'quiet_hours');
assert.equal(g.attempt(base, tokyo('2026-10-23T00:00:00')).reason, 'quiet_hours');
assert.equal(g.attempt(base, tokyo('2026-10-23T06:59:00')).reason, 'quiet_hours');
assert.equal(g.attempt(base, tokyo('2026-10-23T07:00:00')).allowed, true);
// 22:00 exactly is quiet (start inclusive)
assert.equal(g.attempt(base, tokyo('2026-10-23T22:00:00')).reason, 'quiet_hours');
// 21:59 allowed (cap is 3; only 1 sent today so far)
assert.equal(g.attempt(base, tokyo('2026-10-23T21:59:00')).allowed, true);

// 3. Daily cap counts local calendar day, blocked calls don't count
g = createPushGate();
const cap = { ...base, dailyCap: 2 };
assert.equal(g.attempt(cap, tokyo('2026-10-22T08:00:00')).allowed, true);
assert.equal(g.attempt(cap, tokyo('2026-10-22T23:00:00')).reason, 'quiet_hours'); // quiet, not counted
assert.equal(g.attempt(cap, tokyo('2026-10-22T09:00:00')).allowed, true);
assert.equal(g.attempt(cap, tokyo('2026-10-22T10:00:00')).reason, 'daily_cap_reached');
// Next local day resets
assert.equal(g.attempt(cap, tokyo('2026-10-23T08:00:00')).allowed, true);

// 4. Per-user independence
g = createPushGate();
assert.equal(g.attempt({ ...cap, dailyCap: 1 }, tokyo('2026-10-22T08:00:00')).allowed, true);
assert.equal(g.attempt({ ...cap, id: 'u_2', dailyCap: 1 }, tokyo('2026-10-22T08:00:00')).allowed, true);
assert.equal(g.attempt({ ...cap, dailyCap: 1 }, tokyo('2026-10-22T08:30:00')).reason, 'daily_cap_reached');

// 5. Independent gates
assert.equal(createPushGate().attempt({ ...cap, dailyCap: 1 }, tokyo('2026-10-22T08:31:00')).allowed, true);

// 6. Day is the user's zone, not UTC: 2026-10-22 08:00 Tokyo = 23:00 UTC on 10-21
g = createPushGate();
const ny = { id: 'u_ny', timeZone: 'America/New_York', quietStart: '22:00', quietEnd: '07:00', dailyCap: 1 };
// 2026-10-22 10:00 NY (EDT, UTC-4) = 14:00Z
assert.equal(g.attempt(ny, new Date('2026-10-22T14:00:00Z')).allowed, true);
// 2026-10-22 23:00 NY = 2026-10-23T03:00Z: quiet, so check cap via next morning instead
// 2026-10-23 06:30 NY = 10:30Z; same NY date? No, 10-23. Should allow.
assert.equal(g.attempt(ny, new Date('2026-10-23T10:30:00Z')).allowed, true);

// 7. DST: New York spring forward 2026-03-08. 02:30 local doesn't exist; 03:30 EDT.
g = createPushGate();
const dst = { id: 'u_dst', timeZone: 'America/New_York', quietStart: '03:00', quietEnd: '04:00', dailyCap: 5 };
// 2026-03-08 03:30 EDT = 07:30Z -> in quiet window
assert.equal(g.attempt(dst, new Date('2026-03-08T07:30:00Z')).reason, 'quiet_hours');
// 2026-03-08 04:00 EDT = 08:00Z -> end exclusive, allowed
assert.equal(g.attempt(dst, new Date('2026-03-08T08:00:00Z')).allowed, true);

// 8. Equal start and end = empty quiet window
g = createPushGate();
assert.equal(g.attempt({ ...base, quietStart: '00:00', quietEnd: '00:00' }, tokyo('2026-10-22T03:00:00')).allowed, true);

// 9. Zero cap blocks everything
g = createPushGate();
assert.equal(g.attempt({ ...base, dailyCap: 0 }, tokyo('2026-10-22T12:00:00')).reason, 'daily_cap_reached');

// 10. Invalid inputs give distinct codes
g = createPushGate();
const t = tokyo('2026-10-22T12:00:00');
assert.equal(g.attempt({ ...base, id: '' }, t).reason, 'invalid_user');
assert.equal(g.attempt(base, new Date('nope')).reason, 'invalid_time');
assert.equal(g.attempt(base, '2026-10-22'). reason, 'invalid_time');
assert.equal(g.attempt({ ...base, timeZone: 'Mars/Olympus' }, t).reason, 'invalid_time_zone');
assert.equal(g.attempt({ ...base, timeZone: undefined }, t).reason, 'invalid_time_zone');
assert.equal(g.attempt({ ...base, quietStart: '24:00' }, t).reason, 'invalid_quiet_hours');
assert.equal(g.attempt({ ...base, quietEnd: '7:00' }, t).reason, 'invalid_quiet_hours');
assert.equal(g.attempt({ ...base, dailyCap: -1 }, t).reason, 'invalid_daily_cap');
assert.equal(g.attempt({ ...base, dailyCap: 1.5 }, t).reason, 'invalid_daily_cap');
assert.equal(g.attempt({ ...base, dailyCap: '3' }, t).reason, 'invalid_daily_cap');

// 11. Invalid input never counts as a sent push
g = createPushGate();
g.attempt({ ...base, dailyCap: 'x' }, t);
assert.equal(g.attempt({ ...base, dailyCap: 1 }, t).allowed, true);

// 12. Allowed returns exactly the documented shape
const r = createPushGate().attempt(base, t);
assert.deepEqual(Object.keys(r).sort(), ['allowed', 'reason']);

console.log('all checks passed');
EOF
cd /tmp/pushgate-check && node check.mjs

